            }
        }
        login(c, "userA")
        val repo = CampaignRepository(c, localizer)
        val vm = OwnerAppDetailViewModel("c1", repo, localizer)
        try {
            withTimeout(5000) { vm.uiState.first { it.campaign != null && !it.isLoading } }

