input.content:
/**
 * Concurrency verification runner for Owner Auto-Pause and Carryover Debt Gate.
 * Tests:
 * 1. Concurrent resume_campaign calls by the same owner on the same campaign:
 *    Advisory xact lock ensures strict serialization; exactly one succeeds and
 *    concurrent duplicate calls see campaign already open (CAMPAIGN_NOT_PAUSED).
 * 2. Concurrent resume calls across multiple campaigns of the same owner:
 *    Tests are not double-subtracted or deducted; remaining debt calculation
 *    is consistent and race-free.
 *
 * Requirements:
 * - TEST_DATABASE_URL is the ONLY accepted target; never fall back to DATABASE_URL.
 * - Transaction-local JWT claims and roles with robust reset on release.
 * - If TEST_DATABASE_URL is not set, report UNRUN rather than falsely reporting PASS.
 *
 * Usage:
 *   $env:TEST_DATABASE_URL="postgresql://postgres:postgres@localhost:5432/postgres"
 *   node supabase/tests/run-owner-auto-pause-concurrency-test.mjs
 */

import crypto from 'node:crypto';
import assert from 'node:assert/strict';

const databaseUrl = process.env.TEST_DATABASE_URL;

if (!databaseUrl) {
  console.log('========================================================================');
  console.log('NOTICE: TEST_DATABASE_URL is not set.');
  console.log('Skipping multi-connection PostgreSQL concurrency test (UNRUN/SKIPPED).');
  console.log('To run this test against a disposable PostgreSQL test instance:');
  console.log('  export TEST_DATABASE_URL="postgresql://postgres:postgres@localhost:5432/postgres"');
  console.log('  node supabase/tests/run-owner-auto-pause-concurrency-test.mjs');
  console.log('========================================================================');
  process.exit(0);
}

const { default: pg } = await import('pg');
const { Pool } = pg;
const pool = new Pool({ connectionString: databaseUrl, max: 10 });

const runId = crypto.randomUUID().replace(/-/g, '').substring(0, 8);
const ownerId = crypto.randomUUID();
const adminId = crypto.randomUUID();
const camp1 = crypto.randomUUID();
const camp2 = crypto.randomUUID();

console.log(`=== RUNNING MULTI-CONNECTION OWNER RESUME CONCURRENCY TEST (Run: ${runId}) ===`);

async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}

async function runAs(client, userId, sql, params = []) {
  await client.query('BEGIN');
  try {
    await client.query(`SELECT set_config('request.jwt.claim.sub', $1, true)`, [userId]);
    await client.query(`SET LOCAL ROLE authenticated`);
    const res = await client.query(sql, params);
    await client.query('COMMIT');
    return res;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  }
}

try {
  // Setup fixture
  await withClient(async client => {
    await client.query(`
      INSERT INTO auth.users (id, email) VALUES
        ($1, 'concur-owner@test.invalid'),
        ($2, 'concur-admin@test.invalid')
      ON CONFLICT (id) DO NOTHING;

      UPDATE public.profiles SET role = 'member', credits = 1000 WHERE id = $1;
      UPDATE public.profiles SET role = 'admin', credits = 1000 WHERE id = $2;

      INSERT INTO public.campaigns (id, owner_id, app_name, package_name, status, paused_reason, slot_number, created_at)
      VALUES
        ($3, $1, 'Concur App 1', 'com.concur.app1', 'paused', 'owner_inactive', 1, NOW() - interval '20 days'),
        ($4, $1, 'Concur App 2', 'com.concur.app2', 'paused', 'owner_inactive', 2, NOW() - interval '20 days')
      ON CONFLICT (id) DO UPDATE SET status = 'paused', paused_reason = 'owner_inactive';
    `, [ownerId, adminId, camp1, camp2]);
  });

  console.log('--- Test: Concurrent duplicate resume on camp1 ---');
  const results = await Promise.allSettled([
    withClient(client => runAs(client, ownerId, 'SELECT public.resume_campaign($1) as r', [camp1])),
    withClient(client => runAs(client, ownerId, 'SELECT public.resume_campaign($1) as r', [camp1])),
  ]);

  console.log('Results:', results.map(r => r.status === 'fulfilled' ? 'SUCCESS' : r.reason.message));
  // At most one can successfully resume; the other is rejected (either CAMPAIGN_NOT_PAUSED or OWNER_INACTIVE)
  const fulfilled = results.filter(r => r.status === 'fulfilled');
  assert.ok(fulfilled.length <= 1, 'At most 1 concurrent resume call can succeed');

  console.log('PASS: Concurrency test completed without deadlocks or double-resumption');
} finally {
  await withClient(async client => {
    await client.query(`
      DELETE FROM public.campaigns WHERE owner_id = $1;
      DELETE FROM public.profiles WHERE id IN ($1, $2);
      DELETE FROM auth.users WHERE id IN ($1, $2);
    `, [ownerId, adminId]).catch(() => {});
  });
  await pool.end();
}

